window.BOOK={"key":"lamiyyataymiyya","app":"mutoon-lamiyyataymiyya","lsk":"mutoon_lamiyyataymiyya_v1","prefix":"la_","title":"لامية ابن تيمية","sub":"العقيدة · المنسوبة لشيخ الإسلام ابن تيمية (ت ٧٢٨هـ) · ١٦ بيتًا","poems":[{"id":"lamiyyataymiyya","title":"لامية ابن تيمية","nazim":"منسوبة لشيخ الإسلام أبي العباس أحمد بن عبد الحليم ابن تيمية الحراني","death":"ت ٧٢٨هـ","meter":"الكامل","source":"جامع الكتب الإسلامية (عن الشاملة الذهبية): القصيدة اللامية المنسوبة لشيخ الإسلام ابن تيمية، اعتنى بها عبد الله بن محمد الشمراني","srcUrl":"https://ketabonline.com/ar/books/19630","note":"النص المشكول من نشرة الشمراني (١٦ بيتًا)، قوبل كلمةً كلمةً بسكربت بنص اللامية في «بدر التمام» للعقل وبنص البرقاوي وموقع الإسلام سؤال وجواب؛ أُكمل الشكل من العقل وفيما لا يحتمل غيره، وصُحّحت بقايا ترميز وخطآن (أُقِرُّ، وآخَرُ). ونسبتها إلى ابن تيمية مختلَف فيها: نفاها ابن عثيمين وبكر أبو زيد، وأثبتها المرداوي والجبرين وغيرهما.","verses":[["يَا سَائِلِي عَنْ مَذْهَبِي وَعَقِيدَتِي","رُزِقَ الْهُدَى مَنْ لِلْهِدَايَةِ يَسْأَلُ"],["اسْمَعْ كَلَامَ مُحَقِّقٍ فِي قَوْلِهِ","لَا يَنْثَنِي عَنْهُ وَلَا يَتَبَدَّلُ"],["حُبُّ الصَّحَابَةِ كُلِّهِمْ لِي مَذْهَبٌ","وَمَوَدَّةُ الْقُرْبَى بِهَا أَتَوَسَّلُ"],["وَلِكُلِّهِمْ قَدْرٌ عَلَا وَفَضَائِلٌ","لَكِنَّمَا الصِّدِّيقُ مِنْهُمْ أَفْضَلُ"],["وَأَقُولُ فِي الْقُرْآنِ مَا جَاءَتْ بِهِ","آيَاتُهُ فَهْوَ الْكَرِيمُ الْمُنْزَلُ"],["وَأَقُولُ قَالَ اللَّهُ جَلَّ جَلَالُهُ","وَالْمُصْطَفَى الْهَادِي وَلَا أَتَأَوَّلُ"],["وَجَمِيعُ آيَاتِ الصِّفَاتِ أُمِرُّهَا","حَقًّا كَمَا نَقَلَ الطِّرَازُ الْأَوَّلُ"],["وَأَرُدُّ عُهْدَتَهَا إِلَى نُقَّالِهَا","وَأَصُونُهَا عَنْ كُلِّ مَا يُتَخَيَّلُ"],["قُبْحًا لِمَنْ نَبَذَ الْقُرَانَ وَرَاءَهُ","وَإِذَا اسْتَدَلَّ يَقُولُ قَالَ الْأَخْطَلُ"],["وَالْمُؤْمِنُونَ يَرَوْنَ حَقًّا رَبَّهُمْ","وَإِلَى السَّمَاءِ بِغَيْرِ كَيْفٍ يَنْزِلُ"],["وَأُقِرُّ بِالْمِيزَانِ وَالْحَوْضِ الَّذِي","أَرْجُو بِأَنِّي مِنْهُ رَيًّا أَنْهَلُ"],["وَكَذَا الصِّرَاطُ يُمَدُّ فَوْقَ جَهَنَّمٍ","فَمُسَلَّمٌ نَاجٍ وَآخَرُ مُهْمَلُ"],["وَالنَّارُ يَصْلَاهَا الشَّقِيُّ بِحِكْمَةٍ","وَكَذَا التَّقِيُّ إِلَى الْجِنَانِ سَيَدْخُلُ"],["وَلِكُلِّ حَيٍّ عَاقِلٍ فِي قَبْرِهِ","عَمَلٌ يُقَارِنُهُ هُنَاكَ وَيُسْأَلُ"],["هَذَا اعْتِقَادُ الشَّافِعِيِّ وَمَالِكٍ","وَأَبِي حَنِيفَةَ ثُمَّ أَحْمَدَ يُنْقَلُ"],["فَإِنِ اتَّبَعْتَ سَبِيلَهُمْ فَمُوَفَّقٌ","وَإِنِ ابْتَدَعْتَ فَمَا عَلَيْكَ مُعَوَّلُ"]],"secs":{"1":"اللامية"}}],"sharh":false};
